describe('AudioEngine Socket Integration', () => {
    let engine;
    let mockSocket;
    let socketCallbacks = {};

    beforeEach(() => {
        // Setup Mock Socket
        socketCallbacks = {};
        mockSocket = {
            on: vi.fn((event, callback) => {
                socketCallbacks[event] = callback;
            }),
            emit: vi.fn(),
            connect: vi.fn(),
            disconnect: vi.fn(),
            connected: false
        };
        io.mockReturnValue(mockSocket);

        engine = new AudioEngine(() => { });
    });

    afterEach(() => {
        if (engine) engine.stop();
        vi.clearAllMocks();
    });

    it('should initialize socket on start', async () => {
        await engine.start();
        expect(io).toHaveBeenCalled();
        expect(engine.socket).toBe(mockSocket);
    });

    it('should handle socket connection events', async () => {
        await engine.start();

        // Simulate connect
        mockSocket.connected = true;
        if (socketCallbacks['connect']) socketCallbacks['connect']();

        expect(engine.debugInfo.socketConnected).toBe(true);

        // Simulate disconnect
        mockSocket.connected = false;
        if (socketCallbacks['disconnect']) socketCallbacks['disconnect']('transport close');

        expect(engine.debugInfo.socketConnected).toBe(false);
    });

    it('should emit audio_chunk when connected', async () => {
        await engine.start();
        mockSocket.connected = true;

        const pcmData = new Float32Array(128).fill(0.5);
        engine.sendAudioChunk(pcmData);

        expect(mockSocket.emit).toHaveBeenCalledWith('audio_chunk', expect.objectContaining({
            pcm: pcmData,
            sr: 16000
        }));
    });

    it('should buffer chunks when disconnected and flush on connect', async () => {
        await engine.start();
        mockSocket.connected = false;

        const pcmData = new Float32Array(128).fill(0.5);
        engine.sendAudioChunk(pcmData);

        // Should NOT emit yet
        expect(mockSocket.emit).not.toHaveBeenCalled();
        expect(engine.socketBuffer.length).toBe(1);

        // Simulate connection
        mockSocket.connected = true;
        if (socketCallbacks['connect']) socketCallbacks['connect']();

        // Should flush buffer
        expect(mockSocket.emit).toHaveBeenCalledWith('audio_chunk', expect.objectContaining({
            pcm: pcmData
        }));
        expect(engine.socketBuffer.length).toBe(0);
    });

    it('should update latestBackendAnalysis on analysis_update', async () => {
        await engine.start();

        const analysisData = {
            rbi_score: 85,
            breathiness_score: 10,
            roughness_score: 5,
            strain_score: 0
        };

        if (socketCallbacks['analysis_update']) {
            socketCallbacks['analysis_update'](analysisData);
        }

        expect(engine.latestBackendAnalysis).toMatchObject(analysisData);
        expect(engine.latestBackendAnalysis.timestamp).toBeGreaterThan(0);
    });
});

import { useState, useEffect } from 'react';

export const useAchievements = (stats) => {
    const [unlockedAchievement, setUnlockedAchievement] = useState(null);

    const achievements = [
        { id: 'first_session', title: 'First Steps', description: 'Completed your first practice session.', condition: (s) => s.totalSessions >= 1 },
        { id: 'streak_3', title: 'Consistency is Key', description: 'Practiced for 3 days in a row.', condition: (s) => s.currentStreak >= 3 },
        { id: 'master_10', title: 'Dedicated', description: 'Completed 10 practice sessions.', condition: (s) => s.totalSessions >= 10 },
    ];

    useEffect(() => {
        if (!stats) return;

        const unlocked = JSON.parse(localStorage.getItem('gem_achievements') || '[]');

        for (const achievement of achievements) {
            if (!unlocked.includes(achievement.id) && achievement.condition(stats)) {
                // New achievement unlocked!
                setUnlockedAchievement(achievement);
                unlocked.push(achievement.id);
                localStorage.setItem('gem_achievements', JSON.stringify(unlocked));
                break; // Only show one at a time
            }
        }
    }, [stats]);

    const closeAchievement = () => {
        setUnlockedAchievement(null);
    };

    return {
        unlockedAchievement,
        closeAchievement
    };
};

/**
 * KeyboardShortcuts - Global keyboard navigation
 */

import { useEffect, useCallback } from 'react';
import { useNavigation } from '../context/NavigationContext';

const SHORTCUTS = {
    // Navigation
    'g d': { action: 'navigate', target: 'dashboard', description: 'Go to Dashboard' },
    'g p': { action: 'navigate', target: 'practice', description: 'Go to Practice' },
    'g a': { action: 'navigate', target: 'analysis', description: 'Go to Analysis' },
    'g h': { action: 'navigate', target: 'history', description: 'Go to History' },
    'g c': { action: 'navigate', target: 'coach', description: 'Go to Coach' },
    'g s': { action: 'navigate', target: 'settings', description: 'Go to Settings' },

    // Actions
    '?': { action: 'showHelp', description: 'Show keyboard shortcuts' },
    '/': { action: 'search', description: 'Focus search' },
    'Escape': { action: 'close', description: 'Close modal/panel' }
};

/**
 * Hook for keyboard shortcuts
 */
export const useKeyboardShortcuts = (onAction) => {
    const { navigate } = useNavigation();
    let keySequence = '';
    let keyTimeout = null;

    const handleKeyDown = useCallback((event) => {
        // Ignore if typing in input
        if (event.target.tagName === 'INPUT' ||
            event.target.tagName === 'TEXTAREA' ||
            event.target.isContentEditable) {
            return;
        }

        // Build key sequence
        const key = event.key;

        // Clear timeout and reset if too slow
        if (keyTimeout) clearTimeout(keyTimeout);

        keySequence += key === ' ' ? ' ' : key.toLowerCase();

        // Check for match
        const matchedShortcut = SHORTCUTS[keySequence];

        if (matchedShortcut) {
            event.preventDefault();

            switch (matchedShortcut.action) {
                case 'navigate':
                    navigate(matchedShortcut.target);
                    break;
                case 'showHelp':
                    onAction?.('showHelp');
                    break;
                case 'search':
                    onAction?.('search');
                    break;
                case 'close':
                    onAction?.('close');
                    break;
                default:
                    break;
            }

            keySequence = '';
        } else {
            // Reset after delay
            keyTimeout = setTimeout(() => {
                keySequence = '';
            }, 1000);
        }
    }, [navigate, onAction]);

    useEffect(() => {
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [handleKeyDown]);

    return SHORTCUTS;
};

/**
 * Keyboard shortcut help modal content
 */
export const ShortcutsList = () => {
    const shortcutEntries = Object.entries(SHORTCUTS);

    return (
