 * @returns {Object} Prediction results
 */
export const predictProgress = (profile) => {
    const { currentAverages, weeklyTrend } = profile.progress;
    const { goals } = profile;

    // Need baseline data to make predictions
    if (!currentAverages.pitch || !weeklyTrend) {
        return {
            canPredict: false,
            reason: 'Insufficient data'
        };
    }

    // Pitch prediction
    const pitchPrediction = predictMetric(
        currentAverages.pitch,
        weeklyTrend.pitch,
        goals.targetPitchRange.min, // Assuming user wants to reach range min/max
        goals.voiceType === 'masculine' ? goals.targetPitchRange.max : goals.targetPitchRange.min
    );

    // Resonance prediction
    const resonancePrediction = predictMetric(
        currentAverages.resonance,
        weeklyTrend.resonance,
        goals.targetResonance,
        goals.targetResonance
    );

    return {
        canPredict: true,
        pitch: pitchPrediction,
        resonance: resonancePrediction,
        generatedAt: Date.now()
    };
};

/**
 * Predict metric trajectory
 */
const predictMetric = (current, weeklyRate, target, comparisonTarget) => {
    const distance = target - current;
    const isApproaching = (distance > 0 && weeklyRate > 0) || (distance < 0 && weeklyRate < 0);

    if (!isApproaching || Math.abs(weeklyRate) < 0.1) {
        return {
            timeToGoalWeeks: null,
            status: 'plateau', // or diverting
            trajectory: generateTrajectory(current, weeklyRate, 4) // Show next 4 weeks
        };
    }

    // Simple linear projection
    // In reality progress is logarithmic (fast at start, slows down)
    // We'll use a decaying rate model: rate_t = rate_0 * 0.95^t

    let weeks = 0;
    let simulatedValue = current;
    let simulatedRate = weeklyRate;
    const trajectory = [];
    const maxWeeks = 52;

    // Simulation loop
    while (weeks < maxWeeks) {
        trajectory.push(simulatedValue);

        // Check if reached target (within 5% tolerance)
        if (Math.abs(simulatedValue - target) < Math.abs(target * 0.05)) {
            break;
        }

        simulatedValue += simulatedRate;
        simulatedRate *= 0.95; // Assume rate slows down as you get closer/better
        weeks++;
    }

    return {
        timeToGoalWeeks: weeks < maxWeeks ? weeks : '>52',
        status: 'improving',
        confidence: calculateConfidence(weeks),
        trajectory
    };
};

const generateTrajectory = (start, rate, weeks) => {
    const traj = [];
    for (let i = 0; i < weeks; i++) {
        traj.push(start + (rate * i));
    }
    return traj;
};

const calculateConfidence = (weeks) => {
    // Keeping predictions short-term yields higher confidence
    if (weeks < 4) return 0.9;
    if (weeks < 12) return 0.7;
    if (weeks < 24) return 0.5;
    return 0.3;
};

export default {
    predictProgress
};

/**
 * ProgressiveStackingService.js
 * 
 * Manages the state machine for progressive stacking practice sessions.
 * Tracks layer progress, mastery detection, and exploration coverage.
 */

import { STACKING_LAYERS, LAYER_STATUS, DEFAULT_SESSION_CONFIG } from '../data/StackingLayers';

/**
 * Layer progress state
 */
const createLayerState = (layer) => ({
    layerId: layer.id,
    status: LAYER_STATUS.LOCKED,
    holdStartTime: null,
    holdDuration: 0,
    explorationMin: null,
    explorationMax: null,
    explorationCoverage: 0,
    masteryAchieved: false,
    lostTimestamp: null
});

/**
 * ProgressiveStackingService Class
 */
export class ProgressiveStackingService {
    constructor(config = {}) {
        this.config = { ...DEFAULT_SESSION_CONFIG, ...config };
        this.layers = STACKING_LAYERS;
        this.layerStates = {};
        this.currentLayerIndex = 0;
        this.sessionStartTime = null;
        this.onLayerAdvance = null; // Callback for layer advancement
        this.onMastery = null;      // Callback for mastery achievement
        this.onLost = null;         // Callback for lost status

        this._initializeLayerStates();
    }

    _initializeLayerStates() {
        this.layers.forEach((layer, index) => {
            this.layerStates[layer.id] = createLayerState(layer);
        });
        // Unlock first layer
        if (this.layers.length > 0) {
            this.layerStates[this.layers[0].id].status = LAYER_STATUS.ACTIVE;
        }
    }

    /**
     * Start a new session
     */
    startSession() {
        this.sessionStartTime = Date.now();
        this._initializeLayerStates();
        return this.getSessionState();
    }

    /**
     * Reset the session
     */
    resetSession() {
        this.currentLayerIndex = 0;
        this._initializeLayerStates();
        return this.getSessionState();
    }

    /**
     * Get active layers (all unlocked layers up to current)
     */
    getActiveLayers() {
        return this.layers.slice(0, this.currentLayerIndex + 1);
    }

    /**
     * Get current (newest) layer being practiced
     */
    getCurrentLayer() {
        return this.layers[this.currentLayerIndex];
    }

    /**
     * Get layer state by ID
     */
    getLayerState(layerId) {
        return this.layerStates[layerId];
    }

    /**
     * Get full session state for UI rendering
     */
    getSessionState() {
        return {
            currentLayerIndex: this.currentLayerIndex,
            totalLayers: this.layers.length,
            layers: this.layers.map((layer, index) => ({
                ...layer,
                state: this.layerStates[layer.id],
                isActive: index <= this.currentLayerIndex,
                isCurrent: index === this.currentLayerIndex
            })),
            isComplete: this.currentLayerIndex >= this.layers.length,
            sessionDuration: this.sessionStartTime
                ? Date.now() - this.sessionStartTime
                : 0
        };
    }

    /**
     * Process real-time audio data and update layer states
     * @param {Object} audioData - Current audio metrics from dataRef
     * @param {Object} targets - User's target ranges (from calibration)
     * @returns {Object} Updated session state with feedback
     */
    processAudioData(audioData, targets = {}) {
        const now = Date.now();
        const feedback = [];

        // Process each active layer
        this.getActiveLayers().forEach((layer, index) => {
            const state = this.layerStates[layer.id];
            const isCurrent = index === this.currentLayerIndex;
            const value = this._getMetricValue(audioData, layer.metric);
            const target = this._getLayerTarget(layer, targets);

            if (value === null || value === undefined) {
                // No data for this metric
                this._handleNoData(layer, state, now);
                return;
            }

            const isOnTarget = this._checkOnTarget(value, target, layer);

            if (state.status === LAYER_STATUS.MASTERED) {
                // Already mastered - check if still maintaining
                if (!isOnTarget) {
                    this._handleLostMastery(layer, state, now);
                    feedback.push({ layerId: layer.id, type: 'lost', message: `Lost ${layer.name}!` });
                }
            } else if (isCurrent) {
                // Current layer being practiced
                if (layer.targetType === 'exploration') {
                    this._updateExploration(value, layer, state);
                }

                if (isOnTarget) {
                    this._handleOnTarget(layer, state, now, feedback);
                } else {
                    this._handleOffTarget(layer, state, now);
                }
            }
        });

        return {
            ...this.getSessionState(),
            feedback
        };
    }

    /**
     * Get metric value from audio data
     */
    _getMetricValue(audioData, metric) {
        if (!audioData) return null;

        switch (metric) {
            case 'pitch':
                return audioData.pitch;
            case 'f2':
                return audioData.f2 || audioData.formants?.[1];
            case 'tilt':
                return audioData.tilt || audioData.spectralTilt;
            case 'volume':
                return audioData.volume || audioData.rms;
            default:
                return audioData[metric];
        }
    }

    /**
     * Get target for a layer, using calibration if available
     */
    _getLayerTarget(layer, targets) {
        if (targets[layer.id]) {
            return targets[layer.id];
        }

        if (layer.targetType === 'range') {
            return layer.defaultTarget;
        } else if (layer.targetType === 'exploration') {
            return { target: layer.lockTarget, range: layer.explorationRange };
        }

        return layer.defaultTarget;
    }

    /**
     * Check if value is on target
     */
    _checkOnTarget(value, target, layer) {
        if (layer.targetType === 'range') {
            const { min, max } = target;
            return value >= (min - layer.tolerance) && value <= (max + layer.tolerance);
        } else if (layer.targetType === 'exploration') {
            // For exploration, check if near lock target
            const lockTarget = target.target || layer.lockTarget;
            return Math.abs(value - lockTarget) <= layer.tolerance;
        }
        return false;
    }

    /**
     * Update exploration coverage
     */
    _updateExploration(value, layer, state) {
        const range = layer.explorationRange;
        const keys = Object.keys(range);
        const minVal = Math.min(range[keys[0]], range[keys[1]]);
        const maxVal = Math.max(range[keys[0]], range[keys[1]]);

        // Update explored range
        if (state.explorationMin === null || value < state.explorationMin) {
            state.explorationMin = value;
        }
        if (state.explorationMax === null || value > state.explorationMax) {
            state.explorationMax = value;
        }

        // Calculate coverage (clamped to range)
        const exploredRange = Math.min(state.explorationMax, maxVal) -
            Math.max(state.explorationMin, minVal);
        const totalRange = maxVal - minVal;
        state.explorationCoverage = Math.max(0, Math.min(1, exploredRange / totalRange));

        // Mark as exploring if actively exploring
        if (state.status !== LAYER_STATUS.HOLDING && state.status !== LAYER_STATUS.MASTERED) {
            state.status = LAYER_STATUS.EXPLORING;
        }
    }

    /**
     * Handle when on target
     */
    _handleOnTarget(layer, state, now, feedback) {
        // Check exploration requirement
        if (layer.targetType === 'exploration' &&
            state.explorationCoverage < this.config.requireExplorationCoverage) {
            state.status = LAYER_STATUS.EXPLORING;
            return;
        }

        if (!state.holdStartTime) {
            state.holdStartTime = now;
            state.status = LAYER_STATUS.HOLDING;
        }

        state.holdDuration = now - state.holdStartTime;
        state.lostTimestamp = null;

        // Check for mastery
        if (state.holdDuration >= layer.masteryHoldTime && !state.masteryAchieved) {
            state.masteryAchieved = true;
            state.status = LAYER_STATUS.MASTERED;
            feedback.push({
                layerId: layer.id,
                type: 'mastered',
                message: `${layer.name} mastered!`
            });

            if (this.onMastery) {
                this.onMastery(layer);
            }

            // Auto-advance to next layer
            if (this.config.autoAdvance) {
                setTimeout(() => this._advanceToNextLayer(), this.config.celebrationDuration);
            }
        }
    }

    /**
     * Handle when off target
     */
    _handleOffTarget(layer, state, now) {
        if (state.status === LAYER_STATUS.HOLDING) {
            // Start grace period
            if (!state.lostTimestamp) {
                state.lostTimestamp = now;
            } else if (now - state.lostTimestamp > this.config.lostGracePeriod) {
                // Lost after grace period
                state.status = LAYER_STATUS.ACTIVE;
                state.holdStartTime = null;
                state.holdDuration = 0;
                state.lostTimestamp = null;
            }
        }
    }

    /**
     * Handle lost mastery on already-mastered layer
     */
    _handleLostMastery(layer, state, now) {
        state.status = LAYER_STATUS.LOST;
        state.holdStartTime = null;
        state.holdDuration = 0;

        if (this.onLost) {
            this.onLost(layer);
        }

        // After a brief period, reset to active (needs to re-master)
        setTimeout(() => {
            if (state.status === LAYER_STATUS.LOST) {
                state.status = LAYER_STATUS.ACTIVE;
                state.masteryAchieved = false;
            }
        }, 1000);
    }

    /**
     * Handle no data state
     */
    _handleNoData(layer, state, now) {
        if (state.status === LAYER_STATUS.HOLDING) {
            state.holdStartTime = null;
            state.holdDuration = 0;
            state.status = layer.targetType === 'exploration'
                ? LAYER_STATUS.EXPLORING
                : LAYER_STATUS.ACTIVE;
        }
    }

    /**
     * Advance to next layer
     */
    _advanceToNextLayer() {
        if (this.currentLayerIndex < this.layers.length - 1) {
            this.currentLayerIndex++;
            const nextLayer = this.layers[this.currentLayerIndex];
            this.layerStates[nextLayer.id].status = LAYER_STATUS.ACTIVE;

            if (this.onLayerAdvance) {
                this.onLayerAdvance(nextLayer, this.currentLayerIndex);
            }
        }
    }

    /**
     * Manually advance layer (for testing/debug)
     */
    forceAdvance() {
        this._advanceToNextLayer();
        return this.getSessionState();
    }

    /**
     * Get mastery progress as percentage
     */
    getMasteryProgress() {
        const masteredCount = Object.values(this.layerStates)
            .filter(s => s.masteryAchieved).length;
        return (masteredCount / this.layers.length) * 100;
    }

    /**
     * Set callbacks
     */
    setCallbacks({ onLayerAdvance, onMastery, onLost }) {
        if (onLayerAdvance) this.onLayerAdvance = onLayerAdvance;
        if (onMastery) this.onMastery = onMastery;
        if (onLost) this.onLost = onLost;
    }
}

// Singleton instance for easy import
let serviceInstance = null;

export const getStackingService = (config) => {
    if (!serviceInstance) {
        serviceInstance = new ProgressiveStackingService(config);
    }
    return serviceInstance;
};

export const resetStackingService = () => {
    serviceInstance = null;
};

export default ProgressiveStackingService;

/**
 * Quad-Core Voice Analysis Service
 * Implements the "Quad-Core" architecture for voice analysis:
 * 1. Texture (Breathiness) - F3 Noise
 * 2. Health (Flow Phonation) - Spectral Tilt / Onset
 * 3. Color (Resonance) - F2 Frequency
 * 4. Mix (Registration) - Harmonic/Fundamental Ratio
 */
export class QuadCoreAnalysisService {
    constructor() {
        this.history = [];
        this.lastOnset = 0;
        this.isSpeaking = false;
        this.volumeHistory = []; // Track recent volume for onset analysis
        this.lastOnsetQuality = null; // 'soft', 'balanced', 'hard'
    }

    /**
     * Analyze a single frame of audio data
     * @param {Object} data - Audio data from AudioEngine (pitch, tilt, f2, f3Noise, harmonicRatio)
     * @param {Object} targets - User targets (targetPitch, targetF2, etc.)
     * @returns {Object} Analysis results { scores, feedback }
     */
    analyze(data, targets) {
        if (!data || data.volume < 0.01) {
            this.isSpeaking = false;
            return null;
        }

        // Track volume history for onset analysis (keep last 10 frames ~166ms at 60fps)
        this.volumeHistory.push(data.volume);
        if (this.volumeHistory.length > 10) {
            this.volumeHistory.shift();
        }

        // Detect Onset (start of phonation)
        if (!this.isSpeaking && data.volume > 0.02) {
            this.isSpeaking = true;
            this.lastOnset = Date.now();
            this.lastOnsetQuality = this.analyzeOnsetQuality();
        }

        const scores = {
            texture: this.evaluateTexture(data.f3Noise),
            health: this.evaluateHealth(data.tilt, data.volume),
            color: this.evaluateColor(data.f2, targets.targetF2),
            mix: this.evaluateMix(data.harmonicRatio),
            onset: this.lastOnsetQuality ? { quality: this.lastOnsetQuality } : null
        };

        const feedback = this.generateFeedback(scores);

        return {
            timestamp: Date.now(),
            scores,
            feedback
        };
    }

    /**
     * Analyze onset quality based on volume slope
     * Hard onset: Sudden jump in volume (glottal attack)
     * Soft onset: Gradual increase (aspirate/breathy onset)
     * Balanced: Moderate attack (coordinated onset)
     * @returns {'soft'|'balanced'|'hard'} Onset quality
     */
    analyzeOnsetQuality() {
        if (this.volumeHistory.length < 3) return 'balanced';

        // Calculate the rate of volume increase over the last few frames
        const recent = this.volumeHistory.slice(-5);

        // Find the maximum slope between consecutive frames
        let maxSlope = 0;
        for (let i = 1; i < recent.length; i++) {
            const slope = recent[i] - recent[i - 1];
            if (slope > maxSlope) {
                maxSlope = slope;
            }
        }

        // Thresholds based on typical volume ranges (0-1 normalized)
        // Hard onset: Volume jumps more than 0.15 in one frame
        // Soft onset: Volume increases less than 0.03 per frame
        if (maxSlope > 0.15) {
            return 'hard';
        } else if (maxSlope < 0.03) {
            return 'soft';
        }
        return 'balanced';
    }

    /**
     * Module A: Texture (Breathiness)
     * Goal: Detect gender-affirming softness (slight breathiness) vs pressed or whispery.
     * Input: F3 Band Noise (dB)
     */
    evaluateTexture(f3Noise) {
        // Approximate thresholds (dB)
        // -80dB: Very clear/dead silence
        // -60dB to -50dB: Slight Breathiness (Target)
        // > -40dB: Turbulent/Whispery

        let score = 0; // 0=Modal/Pressed, 1=Target, 2=Excessive
        let label = 'Clear';

        if (f3Noise > -45) {
            score = 2; // Excessive
            label = 'Whispery';
        } else if (f3Noise > -65) {
            score = 1; // Target
            label = 'Soft';
        } else {
            score = 0; // Modal
            label = 'Pressed/Clear';
        }

        return { score, label, value: f3Noise };
    }

    /**
     * Module B: Health (Flow Phonation)
     * Goal: Prevent strain.
     * Input: Spectral Tilt (dB/octave estimate)
     */
    evaluateHealth(tilt, volume) {
        // Tilt > -6: Shallow (High high-freq energy) -> Pressed/Bright
        // Tilt < -18: Steep (Low high-freq energy) -> Breathy/Hollow
        // Target: -10 to -15 (Balanced)

        let status = 'Flow'; // Green
        let val = 'Balanced';

        if (tilt > -8) {
            status = 'Pressed'; // Red
            val = 'Strained';
        } else if (tilt < -20) {
            status = 'Breathy'; // Red
            val = 'Weak';
        }

        return { status, label: val, value: tilt };
    }

    /**
     * Module C: Color (Resonance)
     * Goal: Gender brightness.
     * Input: F2 (Hz)
     */
    evaluateColor(f2, targetF2) {
        // Percentage Brightness relative to target
        if (!f2 || !targetF2) return { percentage: 50, label: 'Neutral' };

        // Normalize: <1000Hz (Dark) ... 2500Hz (Bright)
        // If target is 2000Hz (Fem), and user is 1500Hz, they are 75% there?
        // Let's use simpler logic: Deviation from target.

        const diff = f2 - targetF2;
        let percentage = 0;
        let label = 'Neutral';

        if (Math.abs(diff) < 200) {
            percentage = 100;
            label = 'On Target';
        } else if (diff < -200) {
            percentage = Math.max(0, 100 + (diff / 5)); // Drop off
            label = 'Dark';
        } else {
            percentage = Math.max(0, 100 - (diff / 5));
            label = 'Too Bright';
        }

        return { percentage, label, value: f2 };
    }

    /**
     * Module D: Mix (Registration)
     * Goal: Smooth continuity.
     * Input: Harmonic/Fundamental Ratio
     */
    evaluateMix(ratio) {
        // Ratio > 2.0: Harmonic Dominant (Chest/M1)
        // Ratio < 0.5: Fundamental Dominant (Falsetto/M2)
        // 0.5 - 2.0: Mix

        let mixPct = 50; // 50 = Balanced Mix
        let label = 'Mix';

        if (ratio > 2.0) {
            mixPct = 100; // Chest
            label = 'Chest (M1)';
        } else if (ratio < 0.5) {
            mixPct = 0; // Head
            label = 'Head (M2)';
        } else {
            // Linear interpolate between 0.5 and 2.0
            // 0.5 -> 0%, 2.0 -> 100%
            // Normalized: (ratio - 0.5) / 1.5
            mixPct = Math.round(((ratio - 0.5) / 1.5) * 100);
            label = 'Mix';
        }

        return { percentage: mixPct, label, value: ratio };
    }

    /**
     * Synthesis & User Feedback
     * Generates actionable advice based on the combination of modules.
     */
    generateFeedback(scores) {
        // Scenario 0: Hard Onset Warning (prioritize vocal health)
        // Only show this feedback right after a hard onset is detected
        if (scores.onset && scores.onset.quality === 'hard' && Date.now() - this.lastOnset < 500) {
            return {
                type: 'warning',
                title: 'Hard Attack',
                message: "Try starting with a gentle 'h' sound before the vowel. This protects your vocal cords from strain."
            };
        }

        // Scenario 1: The "Strain" Trap
        // Pressed (Health=Pressed) + High Brightness (Color > 80%) + Chest Dominant (Mix > 80%)
        if (scores.health.status === 'Pressed' && scores.mix.percentage > 70) {
            return {
                type: 'warning',
                title: 'Strain Detected',
                message: "You are hitting the pitch, but you are **squeezing**. Try to add a little 'softness' to release the tension."
            };
        }

        // Scenario 2: The "Hollow" Trap
        // Good Texture (Soft) + Flow + Dark (Color < 40%)
        if (scores.texture.label === 'Soft' && scores.health.status === 'Flow' && scores.color.label === 'Dark') {
            return {
                type: 'info',
                title: 'Hollow Tone',
                message: "Great flow and softness! But the tone is a bit dark. Try to **smile slightly** or think of the 'ee' sound."
            };
        }

        // Scenario 3: The "Goldilocks" Result
        // Soft + Flow + On-Target Color + Mix
        if (scores.texture.label === 'Soft' && scores.health.status === 'Flow') {
            // Broad success bucket
            if (scores.color.percentage > 70) {
                return {
                    type: 'success',
                    title: 'Perfect!',
                    message: "This is a healthy, feminine, and resonant tone."
                };
            }
        }

        // Default: Specific corrections
        if (scores.mix.percentage < 20) return { type: 'info', message: "Very light/falsetto. Try to add a bit more vocal weight for a stronger mix." };
        if (scores.mix.percentage > 90) return { type: 'warning', message: "Heavy chest resonance. Try to lighten the weight." };

        return { type: 'neutral', message: "Listening..." };
    }
}

/**
 * QuizService - Spaced Repetition System for Quiz Questions
 * 
 * Implements a simplified SM-2 algorithm for optimal learning retention.
 * Questions progress through states: new → learning → reviewing → mastered
 * 
 * Module-based progression: Users must master module 1 questions before
 * unlocking module 2, following the Feminization Course structure.
 */

import { quizQuestions, getQuestionsByModule } from '../data/quizQuestions';

const STORAGE_KEY = 'gem_quiz_progress';

// Module order matching the course structure
export const MODULE_ORDER = [
    'pitch',        // Module 1: Pitch & Fundamental Frequency
    'formants',     // Module 2: Vocal Formants
    'resonance',    // Module 3: Resonance & Brightness
    'voice-quality',// Module 4: Voice Quality & Timbre
    'intonation',   // Module 5: Intonation & Prosody
    'articulation', // Module 6: Articulation & Speech
    'anatomy',      // Module 7: Vocal Anatomy
    'perception'    // Module 8: Gender Perception
];

export const MODULE_NAMES = {
    'pitch': 'Pitch & Fundamental Frequency',
    'formants': 'Vocal Formants',
    'resonance': 'Resonance & Brightness',
    'voice-quality': 'Voice Quality & Timbre',
    'intonation': 'Intonation & Prosody',
    'articulation': 'Articulation & Speech',
    'anatomy': 'Vocal Anatomy',
    'perception': 'Gender Perception'
};

// Question states
export const QuestionState = {
    NEW: 'new',
    LEARNING: 'learning',
    REVIEWING: 'reviewing',
    MASTERED: 'mastered'
};

// Default question progress
const defaultQuestionProgress = {
    attempts: 0,
    correctCount: 0,
    consecutiveCorrect: 0,
    lastAttempt: null,
    interval: 0, // days until next review
    easeFactor: 2.5,
    dueDate: null,
    state: QuestionState.NEW
};

// Default stats
const defaultStats = {
    totalCorrect: 0,
    totalAttempted: 0,
    currentStreak: 0,
    bestStreak: 0,
    lastSessionDate: null,
    currentModuleIndex: 0, // Start at module 1 (index 0)
    sessionsCompleted: 0
};

class QuizService {
    constructor() {
        this.progress = this.loadProgress();
    }

    /**
     * Load progress from localStorage
     */
    loadProgress() {
        try {
            const stored = localStorage.getItem(STORAGE_KEY);
            if (stored) {
                return JSON.parse(stored);
            }
        } catch (e) {
            console.error('Error loading quiz progress:', e);
        }
        return {
            questions: {},
            stats: { ...defaultStats }
        };
    }

    /**
     * Save progress to localStorage
     */
    saveProgress() {
        try {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(this.progress));
        } catch (e) {
            console.error('Error saving quiz progress:', e);
        }
    }

    /**
     * Get or create progress for a question
     */
    getQuestionProgress(questionId) {
        if (!this.progress.questions[questionId]) {
            this.progress.questions[questionId] = { ...defaultQuestionProgress };
        }
        return this.progress.questions[questionId];
    }

    /**
     * Get current stats
     */
    getStats() {
        return { ...this.progress.stats };
    }

    /**
     * Get current module ID based on progress
     */
    getCurrentModuleId() {
        const moduleIndex = this.progress.stats.currentModuleIndex || 0;
        return MODULE_ORDER[Math.min(moduleIndex, MODULE_ORDER.length - 1)];
    }

    /**
     * Check if a module is fully mastered
     */
    isModuleMastered(moduleId) {
        const moduleQuestions = getQuestionsByModule(moduleId);
        return moduleQuestions.every(q => {
            const progress = this.progress.questions[q.id];
            return progress && progress.state === QuestionState.MASTERED;
        });
    }

    /**
     * Get module progress stats
     */
    getModuleProgress(moduleId) {
        const moduleQuestions = getQuestionsByModule(moduleId);
        let mastered = 0;
        let learning = 0;
        let notStarted = 0;

        moduleQuestions.forEach(q => {
            const progress = this.progress.questions[q.id];
            if (!progress || progress.state === QuestionState.NEW) {
                notStarted++;
            } else if (progress.state === QuestionState.MASTERED) {
                mastered++;
            } else {
                learning++;
            }
        });

        return {
            moduleId,
            moduleName: MODULE_NAMES[moduleId],
            total: moduleQuestions.length,
            mastered,
            learning,
            notStarted,
            isComplete: mastered === moduleQuestions.length,
            percentComplete: Math.round((mastered / moduleQuestions.length) * 100)
        };
    }

    /**
     * Get questions for the next quiz session
     * Uses module-based progression: starts with current module,
     * prioritizing due reviews, then learning, then new questions
     * @param {number} count - Number of questions to return
     */
    getNextQuestions(count = 10) {
        const now = new Date();

        // Check if current module is mastered and advance if needed
        this.checkAndAdvanceModule();

        const currentModuleId = this.getCurrentModuleId();
        const moduleQuestions = getQuestionsByModule(currentModuleId);

        // Categorize questions from current module
        const dueReviews = [];
        const learning = [];
        const newQuestions = [];

        moduleQuestions.forEach(q => {
            const progress = this.progress.questions[q.id];

            if (!progress || progress.state === QuestionState.NEW) {
                newQuestions.push(q);
            } else if (progress.state === QuestionState.MASTERED) {
                // Include mastered questions that are due for review
                if (progress.dueDate && new Date(progress.dueDate) <= now) {
                    dueReviews.push(q);
                }
            } else if (progress.state === QuestionState.REVIEWING) {
                if (!progress.dueDate || new Date(progress.dueDate) <= now) {
                    dueReviews.push(q);
                }
            } else if (progress.state === QuestionState.LEARNING) {
                learning.push(q);
            }
        });

        // Shuffle arrays for variety
        const shuffle = arr => arr.sort(() => Math.random() - 0.5);
        shuffle(dueReviews);
        shuffle(learning);
        shuffle(newQuestions);

        // Combine prioritizing due reviews, then learning, then new
        const combined = [...dueReviews, ...learning, ...newQuestions];

        return combined.slice(0, count);
    }

    /**
     * Check if current module is mastered and advance to next
     */
    checkAndAdvanceModule() {
        const currentModuleId = this.getCurrentModuleId();
        const currentIndex = this.progress.stats.currentModuleIndex || 0;

        if (this.isModuleMastered(currentModuleId) && currentIndex < MODULE_ORDER.length - 1) {
            this.progress.stats.currentModuleIndex = currentIndex + 1;
            this.saveProgress();
            return {
                advanced: true,
                newModuleId: MODULE_ORDER[currentIndex + 1],
                newModuleName: MODULE_NAMES[MODULE_ORDER[currentIndex + 1]]
            };
        }
        return { advanced: false };
    }

    /**
     * Record an answer and update question state
     * @param {string} questionId 
     * @param {boolean} isCorrect 
     */
    recordAnswer(questionId, isCorrect) {
        const progress = this.getQuestionProgress(questionId);
        const stats = this.progress.stats;
        const now = new Date();

        // Update attempt counts
        progress.attempts++;
        progress.lastAttempt = now.toISOString();
        stats.totalAttempted++;

        if (isCorrect) {
            progress.correctCount++;
            progress.consecutiveCorrect++;
            stats.totalCorrect++;
            stats.currentStreak++;

            if (stats.currentStreak > stats.bestStreak) {
                stats.bestStreak = stats.currentStreak;
            }

            // Update state based on consecutive correct answers
            if (progress.state === QuestionState.NEW) {
                progress.state = QuestionState.LEARNING;
                progress.interval = 1;
            } else if (progress.state === QuestionState.LEARNING) {
                if (progress.consecutiveCorrect >= 2) {
                    progress.state = QuestionState.REVIEWING;
                    progress.interval = 3;
                } else {
                    progress.interval = 1;
                }
            } else if (progress.state === QuestionState.REVIEWING) {
                if (progress.consecutiveCorrect >= 4) {
                    progress.state = QuestionState.MASTERED;
                    progress.interval = 7;
                } else {
                    // Increase interval with ease factor
                    progress.interval = Math.round(progress.interval * progress.easeFactor);
                }
                // Increase ease factor (max 2.5)
                progress.easeFactor = Math.min(2.5, progress.easeFactor + 0.1);
            } else if (progress.state === QuestionState.MASTERED) {
                // Mastered questions get longer intervals
                progress.interval = Math.round(progress.interval * progress.easeFactor);
            }
        } else {
            // Wrong answer
            progress.consecutiveCorrect = 0;
            stats.currentStreak = 0;

            // Decrease ease factor (min 1.3)
            progress.easeFactor = Math.max(1.3, progress.easeFactor - 0.2);

            // Reset to learning state if was reviewing/mastered
            if (progress.state === QuestionState.MASTERED || progress.state === QuestionState.REVIEWING) {
                progress.state = QuestionState.LEARNING;
            }

            // Short interval for relearning
            progress.interval = 1;
        }

        // Calculate next due date
        const dueDate = new Date(now);
        dueDate.setDate(dueDate.getDate() + progress.interval);
        progress.dueDate = dueDate.toISOString();

        this.saveProgress();

        return {
            isCorrect,
            newState: progress.state,
            consecutiveCorrect: progress.consecutiveCorrect,
            streak: stats.currentStreak
        };
    }

    /**
     * Complete a quiz session and check for module advancement
     * @param {number} correctInSession - Number of correct answers in this session
     */
    completeSession(correctInSession) {
        const stats = this.progress.stats;
        stats.lastSessionDate = new Date().toISOString();
        stats.sessionsCompleted++;

        // Check if module advanced
        const advancement = this.checkAndAdvanceModule();

        this.saveProgress();

        return {
            correctInSession,
            moduleAdvanced: advancement.advanced,
            newModuleId: advancement.newModuleId || null,
            newModuleName: advancement.newModuleName || null,
            currentModuleId: this.getCurrentModuleId(),
            currentModuleName: MODULE_NAMES[this.getCurrentModuleId()]
        };
    }

    /**
     * Get progress summary with module information
     */
    getProgressSummary() {
        const stats = this.progress.stats;
        const currentModuleId = this.getCurrentModuleId();
        const currentModuleIndex = stats.currentModuleIndex || 0;

        let totalMastered = 0;
        let totalLearning = 0;
        let totalNew = 0;

        // Calculate overall progress
        quizQuestions.forEach(q => {
            const progress = this.progress.questions[q.id];
            if (!progress || progress.state === QuestionState.NEW) {
                totalNew++;
            } else if (progress.state === QuestionState.MASTERED) {
                totalMastered++;
            } else {
                totalLearning++;
            }
        });

        // Get current module progress
        const currentModuleProgress = this.getModuleProgress(currentModuleId);

        // Get all module progress for display
        const allModulesProgress = MODULE_ORDER.map((moduleId, index) => ({
            ...this.getModuleProgress(moduleId),
            isUnlocked: index <= currentModuleIndex,
            isCurrent: index === currentModuleIndex
        }));

        return {
            totalQuestions: quizQuestions.length,
            totalMastered,
            totalLearning,
            totalNew: quizQuestions.length - totalMastered - totalLearning,
            totalCorrect: stats.totalCorrect,
            totalAttempted: stats.totalAttempted,
            accuracy: stats.totalAttempted > 0
                ? Math.round((stats.totalCorrect / stats.totalAttempted) * 100)
                : 0,
            currentStreak: stats.currentStreak,
            bestStreak: stats.bestStreak,
            sessionsCompleted: stats.sessionsCompleted,
            // Module-specific info
            currentModuleId,
            currentModuleName: MODULE_NAMES[currentModuleId],
            currentModuleIndex: currentModuleIndex + 1, // 1-indexed for display
            totalModules: MODULE_ORDER.length,
            currentModuleProgress,
            allModulesProgress
        };
    }

    /**
     * Get due questions count for current module
     */
    getDueCount() {
        const now = new Date();
        let dueCount = 0;

        const currentModuleId = this.getCurrentModuleId();
        const moduleQuestions = getQuestionsByModule(currentModuleId);

        moduleQuestions.forEach(q => {
            const progress = this.progress.questions[q.id];
            if (!progress || progress.state === QuestionState.NEW) {
                dueCount++;
            } else if (progress.dueDate && new Date(progress.dueDate) <= now) {
                dueCount++;
            } else if (progress.state === QuestionState.LEARNING) {
                dueCount++;
            }
        });

        return dueCount;
    }

    /**
     * Reset all progress (for testing)
     */
    resetProgress() {
        this.progress = {
            questions: {},
            stats: { ...defaultStats }
        };
        this.saveProgress();
    }
}

